{
    // Create a central widget and a main vertical layout
    QWidget *centralWidget = new QWidget(this);
    QVBoxLayout *mainLayout = new QVBoxLayout(centralWidget);

    // --- Top section for directory selection ---
    QHBoxLayout *dirLayout = new QHBoxLayout();
    m_pathLineEdit = new QLineEdit();
    m_pathLineEdit->setPlaceholderText("Select a directory containing Excel files...");
    m_pathLineEdit->setReadOnly(true); // Don't allow user to type in path

    QPushButton *browseButton = new QPushButton("Browse...");

    dirLayout->addWidget(m_pathLineEdit);
    dirLayout->addWidget(browseButton);

    // --- Conversion button ---
    m_convertButton = new QPushButton("Convert to CSV");
    m_convertButton->setEnabled(false); // Disabled until a directory is chosen

    // --- Log output area ---
    m_logOutput = new QTextEdit();
    m_logOutput->setReadOnly(true);
    logMessage("Welcome! Please select a directory to begin.");

    // --- Add all parts to the main layout ---
    mainLayout->addLayout(dirLayout);
    mainLayout->addWidget(m_convertButton);
    mainLayout->addWidget(m_logOutput, 1); // The '1' makes the text edit expand

    // Set the central widget
    setCentralWidget(centralWidget);

    // --- Connect signals to slots ---
    connect(browseButton, &QPushButton::clicked, this, &ConverterWindow::onBrowseClicked);
    connect(m_convertButton, &QPushButton::clicked, this, &ConverterWindow::onConvertClicked);
}

