    if (!directory.isEmpty()) {
        m_selectedDirectory = directory;
        m_pathLineEdit->setText(m_selectedDirectory);
        m_convertButton->setEnabled(true); // Enable the convert button
        logMessage(QString("Selected directory: %1").arg(m_selectedDirectory));
    }
}

